example-usage.code:
use kindly_dedup::protection::audit::{
    log_demo_tier_started,
    log_demo_batch_processed,
    log_demo_tier_completed,
    log_demo_verification_passed,
    verify_demo_audit_chain,
};

// 1. Start Accuracy tier
log_demo_tier_started("Accuracy", 100_000, "demo-customer-123")?;

// 2. Process documents with batch logging (every 1M docs)
for batch_num in 1..=10 {
    let docs_processed = batch_num * 1_000_000;
    let throughput = 60_000.0; // docs/sec
    log_demo_batch_processed(batch_num, docs_processed, throughput, "demo-customer-123")?;
}

// 3. Complete tier with metrics
log_demo_tier_completed(
    "Accuracy",
    100_000,
    17.0,        // elapsed_secs
    5882.35,     // throughput
    42,          // cluster_count
    "demo-customer-123"
)?;

// 4. Log verification results
log_demo_verification_passed(
    "Accuracy",
    1.0,    // precision
    1.0,    // recall
    1.0,    // f1_score
    "demo-customer-123"
)?;

// 5. Verify audit chain integrity
let chain_intact = verify_demo_audit_chain()?;
assert!(chain_intact); // Chain should be valid
